package in.tutorlink.controller; import in.tutorlink.entity.*; import in.tutorlink.repository.*; import org.springframework.web.bind.annotation.*; import org.springframework.security.core.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/tuition") public class TuitionController { final TuitionRepository repo; final UserRepository users; public TuitionController(TuitionRepository r,UserRepository u){repo=r;users=u;}
 @GetMapping public List<TuitionRequirement> all(@RequestParam(required=false) String subject,@RequestParam(required=false) String location){return repo.findByActiveTrueOrderByCreatedAtDesc().stream().filter(x->subject==null||x.subjects.stream().anyMatch(s->s.equalsIgnoreCase(subject))).filter(x->location==null||x.location.toLowerCase().contains(location.toLowerCase())).toList();}
 @GetMapping("/{id}") public TuitionRequirement one(@PathVariable Long id){return repo.findById(id).orElseThrow(()->new NoSuchElementException("Tuition requirement not found"));}
 @PostMapping public TuitionRequirement create(@AuthenticationPrincipal Long id,@RequestBody TuitionRequirement t){User u=users.findById(id).orElseThrow();if(u.role!=Role.PARENT)throw new IllegalArgumentException("Only parents can post requirements");t.id=null;t.parent=u;return repo.save(t);}
 @PutMapping("/{id}") public TuitionRequirement update(@AuthenticationPrincipal Long uid,@PathVariable Long id,@RequestBody TuitionRequirement t){var old=one(id);if(!old.parent.id.equals(uid))throw new IllegalArgumentException("Not your requirement");t.id=id;t.parent=old.parent;return repo.save(t);}
 @DeleteMapping("/{id}") public Map<String,Boolean> remove(@AuthenticationPrincipal Long uid,@PathVariable Long id){var t=one(id);if(!t.parent.id.equals(uid))throw new IllegalArgumentException("Not your requirement");t.active=false;repo.save(t);return Map.of("success",true);}}
